namespace Aevrynd {
namespace {
uint32_t Hash(int x,int z,uint32_t seed){uint32_t value=seed^uint32_t(x)*0x9e3779b9u^uint32_t(z)*0x85ebca6bu;value^=value>>16;value*=0x7feb352du;value^=value>>15;value*=0x846ca68bu;value^=value>>16;return value;}
float HashUnit(int x,int z,uint32_t seed){return float(Hash(x,z,seed)&0x00ffffffu)/float(0x01000000u);}
float Smooth(float value){return value*value*(3.f-2.f*value);}
float Lerp(float from,float to,float amount){return from+(to-from)*amount;}
float ValueNoise(float x,float z,uint32_t seed){const int lowX=int(std::floor(x)),lowZ=int(std::floor(z));const float amountX=Smooth(x-float(lowX)),amountZ=Smooth(z-float(lowZ));return Lerp(Lerp(HashUnit(lowX,lowZ,seed),HashUnit(lowX+1,lowZ,seed),amountX),Lerp(HashUnit(lowX,lowZ+1,seed),HashUnit(lowX+1,lowZ+1,seed),amountX),amountZ);}
Color LerpColor(Color from,Color to,float amount){return{Lerp(from.r,to.r,amount),Lerp(from.g,to.g,amount),Lerp(from.b,to.b,amount),Lerp(from.a,to.a,amount)};}
}

void HeightField3D::Configure(HeightFieldSettings3D settings){settings.width=(std::max)(2u,settings.width);settings.depth=(std::max)(2u,settings.depth);settings.cellSize=(std::max)(.05f,settings.cellSize);settings_=settings;heights_.assign(std::size_t(settings.width)*settings.depth,settings.origin.y);minimumHeight_=maximumHeight_=settings.origin.y;}
void HeightField3D::Fill(float height){std::fill(heights_.begin(),heights_.end(),height);minimumHeight_=maximumHeight_=height;}
bool HeightField3D::SetHeight(unsigned x,unsigned z,float height){if(x>=settings_.width||z>=settings_.depth)return false;heights_[Index(x,z)]=height;minimumHeight_=(std::min)(minimumHeight_,height);maximumHeight_=(std::max)(maximumHeight_,height);return true;}
float HeightField3D::Height(unsigned x,unsigned z)const{x=(std::min)(x,settings_.width-1);z=(std::min)(z,settings_.depth-1);return heights_[Index(x,z)];}
Vec3 HeightField3D::SamplePosition(unsigned x,unsigned z)const{return{settings_.origin.x+float(x)*settings_.cellSize,Height(x,z),settings_.origin.z+float(z)*settings_.cellSize};}
bool HeightField3D::Contains(float x,float z)const{return x>=settings_.origin.x&&z>=settings_.origin.z&&x<=settings_.origin.x+float(settings_.width-1)*settings_.cellSize&&z<=settings_.origin.z+float(settings_.depth-1)*settings_.cellSize;}
float HeightField3D::SampleHeight(float x,float z)const{const float localX=Clamp((x-settings_.origin.x)/settings_.cellSize,0.f,float(settings_.width-1)),localZ=Clamp((z-settings_.origin.z)/settings_.cellSize,0.f,float(settings_.depth-1));const unsigned x0=unsigned(std::floor(localX)),z0=unsigned(std::floor(localZ)),x1=(std::min)(x0+1,settings_.width-1),z1=(std::min)(z0+1,settings_.depth-1);const float amountX=localX-float(x0),amountZ=localZ-float(z0);return Lerp(Lerp(Height(x0,z0),Height(x1,z0),amountX),Lerp(Height(x0,z1),Height(x1,z1),amountX),amountZ);}
Vec3 HeightField3D::SampleNormal(float x,float z)const{const float step=settings_.cellSize,left=SampleHeight(x-step,z),right=SampleHeight(x+step,z),back=SampleHeight(x,z-step),front=SampleHeight(x,z+step);return Normalize({left-right,step*2.f,back-front});}
void HeightField3D::RefreshRange(){if(heights_.empty()){minimumHeight_=maximumHeight_=0;return;}const auto [minimum,maximum]=std::minmax_element(heights_.begin(),heights_.end());minimumHeight_=*minimum;maximumHeight_=*maximum;}

void HeightField3D::Generate(uint32_t seed,float amplitude,float frequency,unsigned octaves){amplitude=(std::max)(0.f,amplitude);frequency=(std::max)(.00001f,frequency);octaves=(std::max)(1u,octaves);for(unsigned z=0;z<settings_.depth;++z)for(unsigned x=0;x<settings_.width;++x){const Vec3 position=SamplePosition(x,z);float value{},weight=1.f,totalWeight{},scale=frequency;for(unsigned octave=0;octave<octaves;++octave){value+=(ValueNoise(position.x*scale,position.z*scale,seed+octave*0x9e3779b9u)*2.f-1.f)*weight;totalWeight+=weight;weight*=.5f;scale*=2.f;}heights_[Index(x,z)]=settings_.origin.y+value/totalWeight*amplitude;}RefreshRange();}

void HeightField3D::GenerateNatural(uint32_t seed,HeightFieldNaturalSettings3D settings){settings.amplitude=(std::max)(0.f,settings.amplitude);settings.frequency=(std::max)(.00001f,settings.frequency);settings.ridgeStrength=Clamp(settings.ridgeStrength,0.f,1.f);settings.domainWarp=(std::max)(0.f,settings.domainWarp);settings.octaves=(std::max)(1u,settings.octaves);for(unsigned z=0;z<settings_.depth;++z)for(unsigned x=0;x<settings_.width;++x){const Vec3 position=SamplePosition(x,z);const float warpX=(ValueNoise(position.x*settings.frequency*.42f,position.z*settings.frequency*.42f,seed^0xa511e9b3u)*2.f-1.f)*settings.domainWarp,warpZ=(ValueNoise(position.x*settings.frequency*.42f,position.z*settings.frequency*.42f,seed^0x63d83595u)*2.f-1.f)*settings.domainWarp;float rolling{},ridges{},weight=1.f,totalWeight{},scale=settings.frequency;for(unsigned octave=0;octave<settings.octaves;++octave){const float noise=ValueNoise((position.x+warpX)*scale,(position.z+warpZ)*scale,seed+octave*0x9e3779b9u)*2.f-1.f;rolling+=noise*weight;ridges+=(1.f-std::abs(noise))*weight;totalWeight+=weight;weight*=.5f;scale*=2.f;}const float rollingHeight=rolling/totalWeight,ridgeHeight=(ridges/totalWeight-.52f)*2.f;const float broadValley=ValueNoise(position.x*settings.frequency*.18f,position.z*settings.frequency*.18f,seed^0xc2b2ae35u)*2.f-1.f;const float value=Lerp(rollingHeight,ridgeHeight,settings.ridgeStrength)+broadValley*.32f;heights_[Index(x,z)]=settings_.origin.y+value*settings.amplitude;}RefreshRange();}

bool HeightField3D::GenerateUltra(uint32_t seed,HeightFieldUltraSettings3D settings){
    const std::size_t count=heights_.size();
    if(count==0||count>settings.maximumSamples||count>(std::numeric_limits<std::size_t>::max)()/(sizeof(float)*2u)||count*sizeof(float)*2u>settings.maximumScratchBytes)return false;
    if(!std::isfinite(settings.amplitude)||settings.amplitude<0||settings.amplitude>100000.f||!std::isfinite(settings.frequency)||settings.frequency<=0||settings.frequency>1.f||!std::isfinite(settings.ridgeStrength)||settings.ridgeStrength<0||settings.ridgeStrength>1||!std::isfinite(settings.valleyStrength)||settings.valleyStrength<0||settings.valleyStrength>1||!std::isfinite(settings.domainWarp)||settings.domainWarp<0||!std::isfinite(settings.warpFrequencyScale)||settings.warpFrequencyScale<=0||!std::isfinite(settings.talusSlope)||settings.talusSlope<0||!std::isfinite(settings.depositionStrength)||settings.depositionStrength<0||settings.depositionStrength>1||settings.octaves==0||settings.octaves>12||settings.depositionIterations>12||!std::isfinite(settings.maximumAbsoluteCoordinate)||settings.maximumAbsoluteCoordinate<=0)return false;
    const double maximumX=std::abs(double(settings_.origin.x))+double(settings_.width-1)*settings_.cellSize+settings.domainWarp,maximumZ=std::abs(double(settings_.origin.z))+double(settings_.depth-1)*settings_.cellSize+settings.domainWarp;if(!std::isfinite(maximumX)||!std::isfinite(maximumZ)||maximumX>settings.maximumAbsoluteCoordinate||maximumZ>settings.maximumAbsoluteCoordinate)return false;const double maximumNoiseCoordinate=(std::max)(maximumX,maximumZ)*settings.frequency*std::pow(2.03,double(settings.octaves-1));if(!std::isfinite(maximumNoiseCoordinate)||maximumNoiseCoordinate>double((std::numeric_limits<int>::max)())*.45)return false;
    std::vector<float> generated(count),delta(count);const float rotationSin=.60876143f,rotationCos=.79335334f;
    for(unsigned z=0;z<settings_.depth;++z)for(unsigned x=0;x<settings_.width;++x){const float worldX=settings_.origin.x+float(x)*settings_.cellSize,worldZ=settings_.origin.z+float(z)*settings_.cellSize,warpScale=settings.frequency*settings.warpFrequencyScale;const float warpX=(ValueNoise(worldX*warpScale,worldZ*warpScale,seed^0xa511e9b3u)*2.f-1.f)*settings.domainWarp,warpZ=(ValueNoise(worldX*warpScale,worldZ*warpScale,seed^0x63d83595u)*2.f-1.f)*settings.domainWarp;float rolling{},ridges{},weight=1.f,totalWeight{},scale=settings.frequency,px=worldX+warpX,pz=worldZ+warpZ;for(unsigned octave=0;octave<settings.octaves;++octave){const float sampleX=(px*rotationCos-pz*rotationSin)*scale,sampleZ=(px*rotationSin+pz*rotationCos)*scale,noise=ValueNoise(sampleX,sampleZ,seed+octave*0x9e3779b9u)*2.f-1.f;rolling+=noise*weight;const float ridge=1.f-std::abs(noise);ridges+=(ridge*ridge*2.f-1.f)*weight;totalWeight+=weight;weight*=.5f;scale*=2.03f;px+=warpZ*.037f;pz-=warpX*.031f;}const float broad=ValueNoise(worldX*settings.frequency*.13f,worldZ*settings.frequency*.13f,seed^0xc2b2ae35u)*2.f-1.f,valley=-std::pow((std::max)(0.f,-broad),1.45f);const float base=Lerp(rolling/totalWeight,ridges/totalWeight,settings.ridgeStrength)+valley*settings.valleyStrength;const float height=settings_.origin.y+base*settings.amplitude;if(!std::isfinite(height))return false;generated[Index(x,z)]=height;}
    const float threshold=settings.talusSlope*settings_.cellSize;for(unsigned iteration=0;iteration<settings.depositionIterations;++iteration){std::fill(delta.begin(),delta.end(),0.f);for(unsigned z=1;z+1<settings_.depth;++z)for(unsigned x=1;x+1<settings_.width;++x){const std::size_t center=Index(x,z),left=Index(x-1,z),right=Index(x+1,z),back=Index(x,z-1),front=Index(x,z+1);const float average=(generated[left]+generated[right]+generated[back]+generated[front])*.25f,slope=generated[center]-average;if(slope<=threshold)continue;const float transfer=(slope-threshold)*settings.depositionStrength;delta[center]-=transfer;const float deposited=transfer*.25f;delta[left]+=deposited;delta[right]+=deposited;delta[back]+=deposited;delta[front]+=deposited;}for(std::size_t index=0;index<count;++index)generated[index]+=delta[index];}
    heights_.swap(generated);RefreshRange();return true;
}

void HeightField3D::FlattenCircle(Vec3 center,float innerRadius,float targetHeight,float blendDistance){innerRadius=(std::max)(0.f,innerRadius);blendDistance=(std::max)(0.f,blendDistance);const float outer=innerRadius+blendDistance;for(unsigned z=0;z<settings_.depth;++z)for(unsigned x=0;x<settings_.width;++x){const Vec3 position=SamplePosition(x,z);const float distance=Length(Vec2{position.x-center.x,position.z-center.z});if(distance>outer)continue;const float amount=distance<=innerRadius||blendDistance<=.0001f?1.f:1.f-Smooth((distance-innerRadius)/blendDistance);heights_[Index(x,z)]=Lerp(heights_[Index(x,z)],targetHeight,amount);}RefreshRange();}

Mesh3D HeightField3D::CreateMesh(HeightFieldMeshSettings3D settings)const{Mesh3D mesh;mesh.vertices.reserve(heights_.size());mesh.indices.reserve(std::size_t(settings_.width-1)*(settings_.depth-1)*6);const float range=(std::max)(.0001f,maximumHeight_-minimumHeight_);for(unsigned z=0;z<settings_.depth;++z)for(unsigned x=0;x<settings_.width;++x){const Vec3 position=SamplePosition(x,z),normal=SampleNormal(position.x,position.z);Color color=LerpColor(settings.lowColor,settings.highColor,Clamp((position.y-minimumHeight_)/range,0.f,1.f));if(settings.shoreBlend>0)color=LerpColor(color,settings.shoreColor,Clamp(1.f-std::abs(position.y-settings.shoreHeight)/settings.shoreBlend,0.f,1.f));if(normal.y<settings.steepNormalY)color=LerpColor(color,settings.steepColor,Clamp((settings.steepNormalY-normal.y)/(std::max)(.001f,settings.steepNormalY),0.f,1.f));mesh.vertices.push_back({position.x,position.y,position.z,PackNormalSnorm8(normal),PackColorRgba8(color)});}for(unsigned z=0;z+1<settings_.depth;++z)for(unsigned x=0;x+1<settings_.width;++x){const uint32_t a=z*settings_.width+x,b=a+1,c=a+settings_.width,d=c+1;mesh.indices.insert(mesh.indices.end(),{a,c,b,b,c,d});}return mesh;}

Mesh3D HeightField3D::CreateLodMesh(HeightFieldLodMeshSettings3D lodSettings,HeightFieldMeshSettings3D meshSettings)const{
    Mesh3D mesh;const std::size_t stride=lodSettings.sampleStride;if(stride==0||(stride&(stride-1))!=0||!std::isfinite(lodSettings.skirtDepth)||lodSettings.skirtDepth<0||(lodSettings.includeSkirt&&lodSettings.skirtDepth<=0)||lodSettings.maximumVertices==0||lodSettings.maximumIndices==0)return mesh;
    const std::size_t width=settings_.width,depth=settings_.depth,columns=(width-1)/stride+((width-1)%stride?1u:0u)+1u,rows=(depth-1)/stride+((depth-1)%stride?1u:0u)+1u;if(columns<2||rows<2||columns>(std::numeric_limits<std::size_t>::max)()/rows)return mesh;const std::size_t surfaceVertices=columns*rows;
    if(columns-1>(std::numeric_limits<std::size_t>::max)()/(rows-1))return mesh;const std::size_t quads=(columns-1)*(rows-1);if(quads>(std::numeric_limits<std::size_t>::max)()/6u)return mesh;const std::size_t surfaceIndices=quads*6u,edgeSegments=(columns-1)*2u+(rows-1)*2u;if(edgeSegments>(std::numeric_limits<std::size_t>::max)()/4u)return mesh;const std::size_t skirtVertices=lodSettings.includeSkirt?edgeSegments*4u:0u,skirtIndices=lodSettings.includeSkirt?edgeSegments*6u:0u;if(surfaceVertices>lodSettings.maximumVertices||skirtVertices>lodSettings.maximumVertices-surfaceVertices||surfaceVertices+skirtVertices>std::size_t((std::numeric_limits<uint32_t>::max)())||surfaceIndices>lodSettings.maximumIndices||skirtIndices>lodSettings.maximumIndices-surfaceIndices)return mesh;
    mesh.vertices.reserve(surfaceVertices+skirtVertices);mesh.indices.reserve(surfaceIndices+skirtIndices);const float range=(std::max)(.0001f,maximumHeight_-minimumHeight_);auto coordinate=[](std::size_t index,std::size_t step,std::size_t limit){return unsigned((std::min)(index*step,limit));};auto colorFor=[&](Vec3 position,Vec3 normal){Color color=LerpColor(meshSettings.lowColor,meshSettings.highColor,Clamp((position.y-minimumHeight_)/range,0.f,1.f));if(meshSettings.shoreBlend>0)color=LerpColor(color,meshSettings.shoreColor,Clamp(1.f-std::abs(position.y-meshSettings.shoreHeight)/meshSettings.shoreBlend,0.f,1.f));if(normal.y<meshSettings.steepNormalY)color=LerpColor(color,meshSettings.steepColor,Clamp((meshSettings.steepNormalY-normal.y)/(std::max)(.001f,meshSettings.steepNormalY),0.f,1.f));return PackColorRgba8(color);};
    for(std::size_t row=0;row<rows;++row){const unsigned z=coordinate(row,stride,depth-1);for(std::size_t column=0;column<columns;++column){const unsigned x=coordinate(column,stride,width-1);const Vec3 position=SamplePosition(x,z),normal=SampleNormal(position.x,position.z);mesh.vertices.push_back({position.x,position.y,position.z,PackNormalSnorm8(normal),colorFor(position,normal)});}}
    for(std::size_t row=0;row+1<rows;++row)for(std::size_t column=0;column+1<columns;++column){const uint32_t a=uint32_t(row*columns+column),b=a+1,c=a+uint32_t(columns),d=c+1;mesh.indices.insert(mesh.indices.end(),{a,c,b,b,c,d});}
    if(!lodSettings.includeSkirt)return mesh;auto appendSkirt=[&](std::size_t first,std::size_t second,Vec3 normal){const Vertex3D& firstTop=mesh.vertices[first],&secondTop=mesh.vertices[second];const uint32_t base=uint32_t(mesh.vertices.size()),packedNormal=PackNormalSnorm8(normal);mesh.vertices.push_back({firstTop.x,firstTop.y,firstTop.z,packedNormal,firstTop.color,firstTop.u,firstTop.v});mesh.vertices.push_back({firstTop.x,firstTop.y-lodSettings.skirtDepth,firstTop.z,packedNormal,firstTop.color,firstTop.u,firstTop.v});mesh.vertices.push_back({secondTop.x,secondTop.y,secondTop.z,packedNormal,secondTop.color,secondTop.u,secondTop.v});mesh.vertices.push_back({secondTop.x,secondTop.y-lodSettings.skirtDepth,secondTop.z,packedNormal,secondTop.color,secondTop.u,secondTop.v});mesh.indices.insert(mesh.indices.end(),{base,base+1,base+2,base+2,base+1,base+3});};
    for(std::size_t column=0;column+1<columns;++column){appendSkirt(column+1,column,{0,0,-1});const std::size_t back=(rows-1)*columns;appendSkirt(back+column,back+column+1,{0,0,1});}for(std::size_t row=0;row+1<rows;++row){appendSkirt(row*columns,(row+1)*columns,{-1,0,0});appendSkirt((row+1)*columns+columns-1,row*columns+columns-1,{1,0,0});}return mesh;
}
}
